  function phoneFieldHtml(name,value,placeholder){let val=value||'',codeVal='+51',numVal=val;COUNTRY_CODES.forEach(c=>{if(val.startsWith(c.code)){codeVal=c.code;numVal=val.slice(c.code.length).trim()}});return `<div class="phone-field-wrap"><div class="country-code-select" data-phone-group="${name}"><button type="button" class="country-code-btn" data-toggle-country>${COUNTRY_CODES.find(c=>c.code===codeVal)?.flag||'🌐'} ${codeVal}</button><div class="country-code-dropdown" hidden><input type="search" class="country-code-search" placeholder="${es('Buscar país...','Search country...')}"><div class="country-code-list">${COUNTRY_CODES.map(c=>`<div class="country-code-option" data-cc="${c.code}" data-country="${c.country.toLowerCase()}">${c.flag} ${c.country} <span>${c.code}</span></div>`).join('')}</div></div><input type="hidden" name="${name}CountryCode" value="${escape(codeVal)}"></div><input name="${name}" value="${escape(numVal)}" placeholder="${placeholder||''}" class="phone-number-input"></div>`}
